import { Container, Grid, Typography, Card, CardContent } from "@mui/material";
import "./Skill.css";
import React from "react";

export default function Skill() {
  const skills = {
        "Programming Languages": [
          {
            name: "PHP",
            icon: (
              <svg class="icon icon-php">
                <use xlinkHref="#icon-php"></use>
              </svg>
            ),
          },
          {
            name: "Java",
            icon: (
              <svg class="icon icon-java">
                <use xlinkHref="#icon-java"></use>
              </svg>
            ),
          },
          {
            name: "JavaScript",
            icon: (
              <svg class="icon icon-javascript">
                <use xlinkHref="#icon-javascript"></use>
              </svg>
            ),
          },
          {
            name: "Python",
            icon: (
              <svg class="icon icon-php">
                <use xlinkHref="#icon-python"></use>
              </svg>
            ),
          },
          {
            name: "C++",
            icon: (
              <svg class="icon icon-php">
                <use xlinkHref="#icon-c"></use>
              </svg>
            ),
          },
        ],
        "Frameworks": [
          {
            name: "React",
            icon: (
              <svg class="icon icon-react">
                <use xlinkHref="#icon-react"></use>
              </svg>
            ),
          },
          {
            name: "Node.js",
            icon: (
              <svg class="icon icon-nodejs">
                <use xlinkHref="#icon-nodejs"></use>
              </svg>
            ),
          },
          {
            name: "Express",
            icon: (
              <svg class="icon icon-express">
                <use xlinkHref="#icon-express"></use>
              </svg>
            ),
          },
        ],
  };
  const nameArray = ["Programming Languages", "Frameworks"];

  return (
    <div>
      <Container
        id={"skill"}
        style={{
          paddingTop: "2rem",
          paddingBottom: "2rem",
          marginBottom: "2rem",
          borderRadius: "10px",
        }}
      >
        <Typography
          variant="h2"
          sx={{
            fontWeight: "bold",
            fontSize: "3rem",
            color: "text",
            marginBottom: "1rem",
            textAlign: "center",
          }}
        >
          Skills
        </Typography>
        {nameArray.map((nameArray, i) => (
        <Grid justify="center " container spacing={4}>
        <Grid item>
          <Card
            sx={{
              width: 250,
              marginTop: "1rem",
              marginBottom: "1rem",
              marginLeft: "auto",
              marginRight: "auto",
              boxShadow: "0px 0px 10px 0px rgba(0,0,0,0.2)",
              borderRadius: "10px",
              display: "flex",
              flexDirection: "column",
              justifyContent: "center",
              alignItems: "center",
              padding: "1rem",
            }}
          >
            <CardContent>
              <Typography
                variant="h5"
                sx={{
                  fontWeight: "bold",
                  fontSize: "1.5rem",
                  color: "text",
                  marginBottom: "1.5rem",
                  textAlign: "left",
                }}
              >

                  {nameArray[0]}

              </Typography>
              <Typography
                variant="body2"
                align="left"
                component="text.secondary"
                sx={{
                  fontSize: "1.5rem",
                  color: "text",
                  marginBottom: "1rem",
                }}
              >

                {skills[nameArray[0]].map((skill) => (
                  <div>
                    <Grid container spacing={3}>
                      <Grid item>
                        <Typography
                          variant="h5"
                          align="left"
                          component="text.secondary"
                        >
                          {skill.icon}
                        </Typography>
                      </Grid>
                      <Grid item>
                        <Typography
                          variant="h6"
                          align="left"
                          component="text.secondary"
                        >
                          {skill.name}
                        </Typography>
                      </Grid>
                    </Grid>
                  </div>
                ))}

              </Typography>
            </CardContent>
          </Card>
        </Grid>

      </Grid>    
        ))}
        
      </Container>
    </div>
  );
}
